class ManagedCMSVisitsBoost(OVHModel):
    """
    Information about a visits boost
    """

    created_at: datetime = Field(alias="createdAt")
    """
    Date of creation of the boost
    """
    current_amount: int = Field(alias="currentAmount")
    """
    Current remaining amount of visits offered by the boost
    """
    expires_at: datetime = Field(alias="expiresAt")
    """
    Date of expiration of the boost
    """
    initial_amount: int = Field(alias="initialAmount")
